SELECT COUNT(1)
FROM vm_order_algorithm_config
WHERE delete_flag = 0
  AND algorithm_type = 1
  AND tenant_id = #{tenantId}

      AND accept_node = #{acceptNode}


      AND industry_code = #{industryCode}

  AND device_code = #{deviceCode}
  AND algorithm_code = #{algorithmCode}

SELECT DISTINCT algorithm_code
FROM vm_order_algorithm_config
WHERE delete_flag = 0

    AND algorithm_type = #{algorithmType}


    AND tenant_id = #{tenantId}


    AND accept_node = #{acceptNode}


    AND industry_code = #{industryCode}

SELECT DISTINCT device_code, algorithm_code
FROM vm_order_algorithm_config
WHERE delete_flag = 0

    AND algorithm_type = #{algorithmType}


    AND tenant_id = #{tenantId}


    AND accept_node = #{acceptNode}


    AND industry_code = #{industryCode}
